// Qdrant's /points/query returns { result: { points: [...] } }. Older
// /points/search returned { result: [...] }. Accept either so the workflow
// is not tied to one server minor version.
const payload = $input.first().json || {};
const raw = payload.result?.points ?? payload.result ?? [];
const hits = Array.isArray(raw) ? raw : [];

const q = $('Read Question').first().json;

const kept = hits
  .filter((h) => typeof h?.score === 'number' && h.score >= q.min_score)
  .map((h, i) => ({
    rank: i + 1,
    score: Number(h.score.toFixed(4)),
    source: h.payload?.source ?? 'unknown',
    chunk_index: h.payload?.chunk_index ?? null,
    text: String(h.payload?.text ?? ''),
  }));

return [{
  json: {
    question: q.question,
    collection: q.collection,
    grounded: kept.length > 0,
    hit_count: kept.length,
    searched: hits.length,
    sources: kept.map(({ rank, score, source, chunk_index }) => ({
      rank,
      score,
      source,
      chunk_index,
    })),
    context: kept
      .map((h) => `[${h.rank}] (${h.source}) ${h.text}`)
      .join('\n\n'),
  },
}];

